pub fn command(r: TriRemoteReq, step: u8, out: &mut [u8]) -> usize {
    if (refusal(r) != R_OK) {
        return 0;
    }
    let mut w: usize = 0;
    if (r.op == OP_PING) {
        if (step != 0) {
            return 0;
        }
        w = emit_ssh(out, w, r.host);
        w = emit_str(out, w, "true\n");
        return fits(out, w);
    }
    if (r.op == OP_RUN) {
        let mut run_step: u8 = 2;
        if r.golden {
            run_step = 1;
        }
        if (step == 0) {
            w = emit_ssh(out, w, r.host);
            w = emit_str(out, w, "mkdir -p $HOME/t27-jobs/");
            w = emit_id(out, w, r);
            w = emit_byte(out, w, 10);
            return fits(out, w);
        }
        if ((step == 1) && (r.golden == false)) {
            w = emit_scp(out, w);
            w = emit_str(out, w, r.name);
            w = emit_byte(out, w, 10);
            w = emit_str(out, w, r.host);
            w = emit_str(out, w, ":t27-jobs/");
            w = emit_id(out, w, r);
            w = emit_str(out, w, "/deck.cir\n");
            return fits(out, w);
        }
        if (step == run_step) {
            w = emit_run_head(out, w, r);
            w = emit_script(out, w, r);
            w = emit_str(out, w, "\"\n");
            return fits(out, w);
        }
        return 0;
    }
    if (step != 0) {
        return 0;
    }
    if (r.op == OP_FETCH) {
        w = emit_scp(out, w);
        w = emit_str(out, w, r.host);
        w = emit_str(out, w, ":t27-jobs/");
        w = emit_str(out, w, r.name);
        w = emit_byte(out, w, 47);
        w = emit_str(out, w, r.file);
        w = emit_byte(out, w, 10);
        if (r.dest.len() == 0) {
            w = emit_byte(out, w, 46);
        } else {
            w = emit_str(out, w, r.dest);
        }
        w = emit_str(out, w, "/\n");
        return fits(out, w);
    }
    w = emit_ssh(out, w, r.host);
    if (r.op == OP_STATUS) {
        w = emit_str(out, w, "docker ps -a --filter \"name=^t27job-");
        w = emit_str(out, w, r.name);
        w = emit_str(out, w, "$\" --format \"{{.Names}} {{.Status}}\"\n");
        return fits(out, w);
    }
    if (r.op == OP_LOGS) {
        w = emit_str(out, w, "docker logs --tail 40 t27job-");
        w = emit_str(out, w, r.name);
        w = emit_str(out, w, "; tail -n 40 $HOME/t27-jobs/");
        w = emit_str(out, w, r.name);
        w = emit_str(out, w, "/ngspice.log\n");
        return fits(out, w);
    }
    w = emit_str(out, w, "docker rm -f t27job-");
    w = emit_str(out, w, r.name);
    w = emit_byte(out, w, 10);
    return fits(out, w);
}

pub fn emit_word(out: &mut [u8], w: usize, argv: &[u8], from: usize, to: usize) -> usize {
    let mut bare: bool = (to > from);
    let mut i: usize = from;
    while (i < to) {
        if (is_bare(argv[(i) as usize]) == false) {
            bare = false;
        }
        i = (i + 1);
    }
    let mut p: usize = w;
    if (bare == false) {
        p = emit_byte(out, p, 39);
    }
    i = from;
    while (i < to) {
        if (argv[(i) as usize] == 39) {
            p = emit_str(out, p, "'\\''");
        } else {
            p = emit_byte(out, p, argv[(i) as usize]);
        }
        i = (i + 1);
    }
    if (bare == false) {
        p = emit_byte(out, p, 39);
    }
    return p;
}

pub fn shell_form(argv: &[u8], n: usize, out: &mut [u8]) -> usize {
    let mut w: usize = 0;
    let mut s: usize = 0;
    while (s < n) {
        let mut e: usize = s;
        while ((e < n) && (argv[(e) as usize] != 10)) {
            e = (e + 1);
        }
        if (s > 0) {
            w = emit_byte(out, w, 32);
        }
        w = emit_word(out, w, argv, s, e);
        s = (e + 1);
    }
    return fits(out, w);
}

