pub const V_BEHIND: u8 = 2;

pub const V_BLOCKED: u8 = 3;

pub const V_NOT_RUN: u8 = 4;

pub const V_RED: u8 = 5;

pub const V_VACUOUS: u8 = 1;

pub const V_VERIFIED: u8 = 0;

pub fn glob(pat: &'static str, s: &'static str, from: usize, to: usize) -> bool {
    let mut p: usize = 0;
    let mut i: usize = from;
    let mut star: usize = pat.len();
    let mut mark: usize = from;
    while (i < to) {
        if ((p < pat.len()) && ((pat.as_bytes()[(p) as usize] == 63) || (pat.as_bytes()[(p) as usize] == s.as_bytes()[(i) as usize]))) {
            p = (p + 1);
            i = (i + 1);
        } else {
            if ((p < pat.len()) && (pat.as_bytes()[(p) as usize] == 42)) {
                star = p;
                mark = i;
                p = (p + 1);
            } else {
                if (star == pat.len()) {
                    return false;
                }
                p = (star + 1);
                mark = (mark + 1);
                i = mark;
            }
        }
    }
    while ((p < pat.len()) && (pat.as_bytes()[(p) as usize] == 42)) {
        p = (p + 1);
    }
    return (p == pat.len());
}

pub fn name(v: u8) -> &'static str {
    if (v == V_VERIFIED) {
        return "verified";
    }
    if (v == V_VACUOUS) {
        return "vacuous";
    }
    if (v == V_BEHIND) {
        return "behind";
    }
    if (v == V_BLOCKED) {
        return "blocked";
    }
    if (v == V_NOT_RUN) {
        return "not-run";
    }
    if (v == V_RED) {
        return "RED";
    }
    return "UNREAD";
}

pub fn span_is(text: &'static str, from: usize, to: usize, lit: &'static str) -> bool {
    if ((to < from) || ((to - from) != lit.len())) {
        return false;
    }
    let mut k: usize = 0;
    while (k < lit.len()) {
        if (text.as_bytes()[((from + k)) as usize] != lit.as_bytes()[(k) as usize]) {
            return false;
        }
        k = (k + 1);
    }
    return true;
}

pub fn why(v: u8) -> &'static str {
    if (v == V_VERIFIED) {
        return "verified: t27b passes with runtime asserts";
    }
    if (v == V_VACUOUS) {
        return "vacuous: it passes with 0 runtime asserts";
    }
    if (v == V_BEHIND) {
        return "behind: the reference passes, t27b is blocked";
    }
    if (v == V_BLOCKED) {
        return "blocked: neither the reference nor t27b runs it";
    }
    if (v == V_NOT_RUN) {
        return "not run: the lab ran only the reference";
    }
    if (v == V_RED) {
        return "RED: a failure, timeout, crash or mismatch";
    }
    return "UNREAD: the lab's result for it cannot be read";
}

